// The key difference between auto and template type deduction.

auto x = { 11, 23, 9 }; // OK: x is std::initializer_list<int>

template<typename T>
void f(T param);

// f({ 11, 23, 9 }); // Error! Cannot deduce T from a braced initializer list.

// To make the template work, it must be specialized for std::initializer_list
template<typename T>
void g(std::initializer_list<T> param);

g({ 11, 23, 9 }); // OK: T is deduced as int.
